import functools
import pytest
from fastapi import FastAPI
from typing import ForwardRef

app = FastAPI()

class MyModel:
    pass

def my_function(a: "MyModel"):
    return a

@functools.wraps(my_function)
def wrapped_function(a: "MyModel"):
    return my_function(a)

def test_wrapped_method_type_inference():
    # We want to see if FastAPI can handle a wrapped function with forward references
    # The issue is in get_typed_signature which is called during route registration

    # To reproduce, we need to register a route with a wrapped function
    # that has forward references in its annotations.

    try:
        app.add_api_route("/test", wrapped_function)
    except NameError as e:
        pytest.fail(f"NameError encountered: {e}")
    except Exception as e:
        pytest.fail(f"Unexpected exception: {e}")

    # If it doesn't fail, we check if the type was correctly inferred
    for route in app.routes:
        if route.path == "/test":
            assert route.dependant is not None

